let elapsed=0,frames=0,lastHud=0;app.on('update',dt=>{elapsed+=dt;frames++;if(elapsed>1){fps=Math.round(frames/elapsed);elapsed=0;frames=0}if(!game){const t=performance.now()/1000;camera.setPosition(10+Math.sin(t*.08)*1.3,3.2,15);camera.lookAt(2,1.3,5);preview.legs.forEach((l,i)=>l.setLocalEulerAngles(Math.sin(t*1.5+i)*2,0,0));return}for(let i=effects.length-1;i>=0;i--)if(Date.now()>effects[i].end){effects[i].e.destroy();effects.splice(i,1)}for(const g of state?.grenades||[]){if(!projectileModels.has(g.id))projectileModels.set(g.id,mesh('grenade',[g.x,g.y,g.z],[.2,.2,.2],sand,app.root,'sphere'));projectileModels.get(g.id).setPosition(g.x,g.y,g.z)}for(const [id,e] of projectileModels)if(!state?.grenades?.some(g=>g.id===id)){e.destroy();projectileModels.delete(id)}if(keys.fire)fire();const me=state?.players.find(p=>p.id===myId);for(const p of state?.players||[]){const obj=models.get(p.id);obj.e.enabled=p.hp>0&&(p.id!==myId||tps);const pos=obj.e.getPosition(),tx=p.id===myId?local.x:p.x,tz=p.id===myId?local.z:p.z;obj.e.setPosition(pc.math.lerp(pos.x,tx,Math.min(1,dt*14)),p.id===myId?local.y:p.y,pc.math.lerp(pos.z,tz,Math.min(1,dt*14)));obj.e.setEulerAngles(0,p.id===myId?yaw*180/Math.PI:p.yaw*180/Math.PI,0);const moving=Math.abs(pos.x-tx)+Math.abs(pos.z-tz)>.02;obj.legs.forEach((l,i)=>l.setLocalEulerAngles(moving?Math.sin(performance.now()*.012+i*Math.PI)*28:0,0,0))}const eye=new pc.Vec3(local.x,local.y+(keys.KeyC?1.2:1.65),local.z),dir=new pc.Vec3(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch));let dist=tps?(aim?1.4:3.6):0;if(tps){const back=[-dir.x,-dir.y,-dir.z];for(const b of boxes){const t=rayBoxLocal([eye.x,eye.y,eye.z],back,b);dist=Math.min(dist,Math.max(0,t-.2))}}camera.setPosition(eye.x-dir.x*dist+(tps?.4*Math.cos(yaw):0),eye.y-dir.y*dist+(tps?.25:0),eye.z-dir.z*dist-(tps?.4*Math.sin(yaw):0));camera.setEulerAngles(pitch*180/Math.PI,yaw*180/Math.PI,0);camera.camera.fov=aim?50:70;gun.enabled=!tps&&!!me&&me.hp>0;gun.setLocalPosition(aim?-.29:0,me?.reloadAt?-.2:0,Date.now()-lastFire<80?.08:0);if(performance.now()-lastHud>100){lastHud=performance.now();renderHud(me)}});
function rayBoxLocal(o,d,b){let lo=0,hi=1e5;for(let k=0;k<3;k++){if(Math.abs(d[k])<.00001){if(o[k]<b[k]-b[k+3]/2||o[k]>b[k]+b[k+3]/2)return 1e5;continue}let a=(b[k]-b[k+3]/2-o[k])/d[k],c=(b[k]+b[k+3]/2-o[k])/d[k];if(a>c)[a,c]=[c,a];lo=Math.max(lo,a);hi=Math.min(hi,c);if(hi<lo)return 1e5}return lo}
